import java.io.*;
import java.nio.file.*;

public class FileServer {
    public void readFile(String filename) throws IOException {
        Path baseDir = Paths.get("/var/www/uploads/").toAbsolutePath().normalize();

        // Resolve the user input against the base directory
        Path filePath = baseDir.resolve(filename).toAbsolutePath().normalize();

        // SECURITY FIX: Verify that the resulting path still starts with the intended base directory.
        // This prevents "Path Traversal" attacks by ensuring the user cannot escape the sandbox.
        if (!filePath.startsWith(baseDir)) {
            throw new SecurityException("Access Denied: Invalid file path.");
        }

        byte[] content = Files.readAllBytes(filePath);
        System.out.println(new String(content));
    }
}
