    "startup_name": "Tipperary",
    "tagline": "Know the norm. Tip with confidence.",
    "structure": {
      "problem_statement": {
        "headline": "The Social Anxiety of the Check",
        "description": "Dining out is meant to be enjoyable, but the moment the bill arrives, a wave of social anxiety hits. Customers are constantly guessing: 'Is 15% too low? Is 25% overkill? Am I being cheap or overpaying?'",
        "pain_points": [
          "Inconsistent tipping cultures across different cuisines and service levels.",
          "Social awkwardness and fear of being judged by staff or peers.",
          "Lack of transparency in service expectations."
        ]
      },
      "solution": {
        "headline": "Data-Driven Dining Etiquette",
        "description": "Tipperary is a real-time, crowdsourced intelligence platform that provides the 'true average' tip percentage for any specific restaurant, neighborhood, or service type.",
        "key_features": [
          "Real-time Tip Heatmaps: See the average tip percentage for a restaurant in the last 30 days.",
          "Service Level Filters: Distinguish between casual cafe service and fine-dining expectations.",
          "Seamless Integration: Scan a receipt or link your digital payment to anonymously contribute to the data pool.",
          "Cultural Guides: Instant insights into tipping norms for international travel."
        ]
      },
      "market_opportunity": {
        "target_audience": [
          "Gen Z and Millennial diners (the 'socially conscious' and 'data-driven' cohorts).",
          "Frequent travelers and expats.",
          "Food enthusiasts and Yelp/Google Maps power users."
        ],
        "market_gap": "While Yelp reviews food and Google reviews service, no platform currently quantifies the economic etiquette of the dining experience."
      },
      "business_model": {
        "revenue_streams": [
          "Freemium Model: Basic data is free; 'Premium Dining Insights' (historical trends and high-end concierge data) requires a subscription.",
          "B2B Analytics: Selling anonymized, aggregated tipping trend data to restaurant groups to help them optimize staff compensation and turnover.",
          "Affiliate Partnerships: Integration with reservation platforms like OpenTable."
        ]
      },
      "competitive_advantage": {
        "moat": "The Network Effect. As more users scan receipts and contribute data, our proprietary 'Tip Index' becomes the industry standard, making it impossible for competitors to replicate the depth of our localized data."
      },
      "the_vision": {
        "closing_statement": "We aren't just building an app; we are building the global standard for service transparency. With Tipperary, we are removing the guesswork from generosity, ensuring fair pay for workers and peace of mind for diners. Let's make tipping effortless."
      }
    }
  }
}
